import{_ as l,D as s,h as c,c as m,b as t,e as a,G as d,ab as o,t as n}from"./chunks/framework.DLPCC8AC.js";const _=JSON.parse('{"title":"规范","description":"TOON 规范导览：章节结构、合规性检查清单、媒体类型和版本管理。","frontmatter":{"description":"TOON 规范导览：章节结构、合规性检查清单、媒体类型和版本管理。"},"headers":[],"relativePath":"zh/reference/spec.md","filePath":"zh/reference/spec.md","lastUpdated":1785197822000}'),p={name:"zh/reference/spec.md"};function h(r,e,b,f,g,u){const i=s("CopyOrDownloadAsMarkdownButtons");return c(),m("div",null,[e[0]||(e[0]=t("div",{style:{display:"none"},hidden:"true","aria-hidden":"true","data-nosnippet":""},"Are you an LLM? You can read better optimized documentation at /zh/reference/spec.md for this page in Markdown format",-1)),e[1]||(e[1]=t("h1",{id:"规范",tabindex:"-1"},[a("规范 "),t("a",{class:"header-anchor",href:"#规范","aria-label":'Permalink to "规范"'},"​")],-1)),d(i),e[2]||(e[2]=o('<p><a href="https://github.com/toon-format/spec" target="_blank" rel="noreferrer">TOON 规范</a> 是实现编码器、解码器和校验器的权威参考。它定义了具体语法、规范性的编码/解码行为，以及严格模式下的校验规则。</p><p>如果只是<em>使用</em> TOON，无需阅读本页；本页主要面向实现者和贡献者。如果你想学习如何使用 TOON，请从 <a href="/zh/guide/getting-started.html">快速开始</a> 指南入手。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>TOON 规范已经稳定，但仍在持续演进中。规范并非一成不变，欢迎通过贡献内容或分享反馈来参与其后续发展。</p></div><h2 id="当前版本" tabindex="-1">当前版本 <a class="header-anchor" href="#当前版本" aria-label="Permalink to &quot;当前版本&quot;">​</a></h2>',4)),t("p",null,[t("strong",null,"规范 v"+n(r.$spec.version),1),a("（"+n(r.$spec.date)+"）是当前已发布的工作草案。该版本已足够稳定并可作为实现依据，但尚未定稿；详情请参阅规范中的 “Status of This Document” 部分。",1)]),e[3]||(e[3]=o('<h2 id="媒体类型与文件扩展名" tabindex="-1">媒体类型与文件扩展名 <a class="header-anchor" href="#媒体类型与文件扩展名" aria-label="Permalink to &quot;媒体类型与文件扩展名&quot;">​</a></h2><p>规范在 <a href="https://github.com/toon-format/spec/blob/main/SPEC.md#17-iana-considerations" target="_blank" rel="noreferrer">§17</a> 中定义了临时媒体类型和文件扩展名：</p><ul><li><strong>媒体类型：</strong> <code>text/toon</code>（临时，尚未在 IANA 注册；仅支持 UTF-8）</li><li><strong>文件扩展名：</strong> <code>.toon</code></li></ul><p>TOON 文档始终使用 UTF-8 编码和 LF（<code>\\n</code>）换行符；可选的 <code>charset</code> 参数如果存在，其值为 <code>utf-8</code>。</p><h2 id="规范导览" tabindex="-1">规范导览 <a class="header-anchor" href="#规范导览" aria-label="Permalink to &quot;规范导览&quot;">​</a></h2><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#1-terminology-and-conventions" target="_blank" rel="noreferrer">§1 术语与约定</a>： 定义了“缩进层级”“生效分隔符”“严格模式”等关键术语，以及 RFC2119 关键词（MUST、SHOULD、MAY）。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#2-data-model" target="_blank" rel="noreferrer">§2 数据模型</a>： 规定了 JSON 数据模型（对象、数组、基本类型）、数组和对象的顺序要求，以及规范数字格式（位于 <code>[1e-6, 1e21)</code> 范围内或为零的值使用规范十进制；超出该范围允许使用指数记法）。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#3-encoding-normalization-reference-encoder" target="_blank" rel="noreferrer">§3 编码规范化</a>： 定义了非 JSON 类型（Date、BigInt、NaN、Infinity、undefined 等）在编码前应如何规范化。编码器实现者应重点阅读这一节。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#4-decoding-interpretation-reference-decoder" target="_blank" rel="noreferrer">§4 解码解释</a>： 规定了解码器如何将文本标记映射为宿主语言中的值（带引号的字符串、不带引号的基本类型，以及解析数字时对前导零的处理）。在参考实现中，解码器默认启用严格模式（<code>strict = true</code>）；严格模式错误见 §14。</p><h3 id="语法规则" tabindex="-1">语法规则 <a class="header-anchor" href="#语法规则" aria-label="Permalink to &quot;语法规则&quot;">​</a></h3><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#5-concrete-syntax-and-root-form" target="_blank" rel="noreferrer">§5 具体语法与根形式</a>： 定义了 TOON 这种面向行、基于缩进的表示法，并说明如何判断根值是对象、数组还是基本类型。§5.1 定义了整行注释，注释会在其他任何处理之前通过词法预处理移除。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#6-header-syntax-normative" target="_blank" rel="noreferrer">§6 首部语法</a>： 给出数组首部和带键首部的规范性 ABNF 语法：<code>key[N&lt;delim?&gt;]{fields}:</code> 和 <code>key[N:&lt;delim?&gt;]{fields}:</code>。该节规定了方括号片段、分隔符符号和字段列表，包括嵌套字段组。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#7-strings-and-keys" target="_blank" rel="noreferrer">§7 字符串与键</a>： 完整的引号规则（字符串何时必须加引号）、合法转义序列（仅包括 <code>\\\\</code>、<code>\\&quot;</code>、<code>\\n</code>、<code>\\r</code>、<code>\\t</code>，以及用于其他 U+0000–U+001F 控制字符的 <code>\\uXXXX</code>），以及键的编码要求。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#8-objects" target="_blank" rel="noreferrer">§8 对象</a>： 对象字段编码（<code>key: value</code>）、嵌套规则、键顺序保留，以及空对象处理。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#9-arrays-and-tabular-forms" target="_blank" rel="noreferrer">§9 数组与表格形式</a>： 涵盖所有数组形式：基本类型数组（内联）、对象数组（表格化，包括嵌套字段组）、混合数组/非一致数组（列表）、数组的数组，以及一致对象映射的带键表格形式（§9.5）。该节还包括各类形式的检测要求。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#10-objects-as-list-items" target="_blank" rel="noreferrer">§10 作为列表项的对象</a>： 列表项中对象的缩进规则（第一个字段位于连字符所在行），包括第一个字段为表格化数组或带键表格对象时的规范模式（首部位于连字符所在行，行数据缩进深度为 +2，同级字段缩进深度为 +1）。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#11-delimiters" target="_blank" rel="noreferrer">§11 分隔符</a>： 分隔符作用域（文档级分隔符与生效分隔符）、基于分隔符的引号处理，以及逗号、制表符、竖线分隔符的解析规则。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#12-indentation-and-whitespace" target="_blank" rel="noreferrer">§12 缩进与空白</a>： 编码要求（一致的空格缩进、缩进中不允许使用制表符、无行尾空格/换行符）以及解码规则（严格和非严格缩进处理）。</p><h3 id="合规性与校验" tabindex="-1">合规性与校验 <a class="header-anchor" href="#合规性与校验" aria-label="Permalink to &quot;合规性与校验&quot;">​</a></h3><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#13-conformance-and-options" target="_blank" rel="noreferrer">§13 合规性与选项</a>： 定义了合规类型（编码器、解码器、校验器）、标准化选项以及合规检查清单。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#14-strict-mode-errors-and-diagnostics-authoritative-checklist" target="_blank" rel="noreferrer">§14 严格模式下的错误与诊断</a>： 严格模式下各类错误的<strong>权威检查清单</strong>：数组与条目数量、宽度不匹配（§14.1）、语法和结构错误（§14.2），以及重复的同级键（§14.3）。</p><h3 id="实现指导" tabindex="-1">实现指导 <a class="header-anchor" href="#实现指导" aria-label="Permalink to &quot;实现指导&quot;">​</a></h3><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#15-security-considerations" target="_blank" rel="noreferrer">§15 安全考量</a>： 与安全相关的注入风险、引号规则和严格模式检查。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#16-internationalization" target="_blank" rel="noreferrer">§16 国际化</a>： Unicode 处理，以及不受语言环境影响的数字文本格式。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#17-iana-considerations" target="_blank" rel="noreferrer">§17 IANA 考量</a>： 媒体类型注册计划及临时状态。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#18-versioning-and-extensibility" target="_blank" rel="noreferrer">§18 版本管理与可扩展性</a>： 规范的演进方式：主版本和次版本变更，以及可扩展性策略。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#19-intellectual-property-considerations" target="_blank" rel="noreferrer">§19 知识产权考量</a>： 规范的许可和知识产权条款。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#appendix-e-host-type-normalization-examples-informative" target="_blank" rel="noreferrer">附录 E：宿主类型规范化示例</a>： 为 Go、JavaScript、Python、Rust 和 Java 实现提供参考说明，介绍各语言特有类型的规范化方式。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#appendix-c-test-suite-and-compliance-informative" target="_blank" rel="noreferrer">附录 C：测试套件与合规性</a>： 位于 <a href="https://github.com/toon-format/spec/tree/main/tests" target="_blank" rel="noreferrer">github.com/toon-format/spec/tree/main/tests</a> 的参考测试套件，可用于校验各实现。</p><h2 id="合规性检查清单" tabindex="-1">合规性检查清单 <a class="header-anchor" href="#合规性检查清单" aria-label="Permalink to &quot;合规性检查清单&quot;">​</a></h2><p>规范按合规类别提供一份清单；请按你正在构建的组件阅读对应清单。SPEC.md 中的清单才是权威版本，其他位置的摘要可能随时间偏离。</p><ul><li><strong><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#131-encoder-conformance-checklist" target="_blank" rel="noreferrer">编码器检查清单（§13.1）</a></strong>：输出不变式，包括 UTF-8/LF、一致缩进、引号与转义、<code>[N]</code> 长度、规范数字、键顺序、无注释行、无尾随空白。</li><li><strong><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#132-decoder-conformance-checklist" target="_blank" rel="noreferrer">解码器检查清单（§13.2）</a></strong>：解析职责，包括注释预处理、首部解析、生效分隔符拆分、token 类型判定、严格模式执行、顺序保留。</li><li><strong><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#133-validator-conformance-checklist" target="_blank" rel="noreferrer">校验器检查清单（§13.3）</a></strong>：结构和空白不变式、分隔符一致性、声明数量，以及所有严格模式规则。</li></ul><h2 id="版本管理" tabindex="-1">版本管理 <a class="header-anchor" href="#版本管理" aria-label="Permalink to &quot;版本管理&quot;">​</a></h2><p>规范使用语义化版本（主版本号、次版本号）：</p><ul><li><strong>主版本</strong>（例如 v2 → v3）：破坏性变更，与之前版本不兼容</li><li><strong>次版本</strong>（例如 v3.1 → v3.2）：澄清说明、新增要求，或向后兼容的补充内容</li></ul><p>详细版本历史请参阅 <a href="https://github.com/toon-format/spec/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG.md</a>，版本策略请参阅 <a href="https://github.com/toon-format/spec/blob/main/VERSIONING.md" target="_blank" rel="noreferrer">VERSIONING.md</a>。</p><h2 id="为规范做贡献" tabindex="-1">为规范做贡献 <a class="header-anchor" href="#为规范做贡献" aria-label="Permalink to &quot;为规范做贡献&quot;">​</a></h2><p>该规范由社区在 <a href="https://github.com/toon-format/spec" target="_blank" rel="noreferrer">github.com/toon-format/spec</a> 上维护；欢迎报告歧义、提出澄清说明，或向参考测试套件添加测试用例。</p>',39))])}const P=l(p,[["render",h]]);export{_ as __pageData,P as default};
